import type { ComboboxPrefixProps } from "../combobox.types";

import { forwardRef } from "react";
import { Input } from "@components/input";
import { Search } from "@exp-textura/icons";

const ComboboxPrefix = forwardRef<HTMLDivElement, ComboboxPrefixProps>(
  ({ children, ...props }, ref) => {
    return (
      <Input.Prefix ref={ref} {...props}>
        {children || <Search />}
      </Input.Prefix>
    );
  },
);

ComboboxPrefix.displayName = "Combobox.InputPrefix";

export { ComboboxPrefix };
